package exercise

import (
	"reflect"
	"testing"
	"time"
)

func buildAdj(n int, edges [][2]int) [][]int {
	adj := make([][]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1])
		adj[e[1]] = append(adj[e[1]], e[0])
	}
	return adj
}

func sameVertices(got, want []int) bool {
	if len(got) == 0 && len(want) == 0 {
		return true
	}
	return reflect.DeepEqual(got, want)
}

func TestArticulationPointsSmallGraphs(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges [][2]int
		want  []int
	}{
		{
			name:  "triangle with a tail",
			n:     5,
			edges: [][2]int{{0, 1}, {0, 2}, {1, 2}, {0, 3}, {3, 4}},
			want:  []int{0, 3},
		},
		{
			name:  "cycle hanging off a single vertex",
			n:     4,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 3}, {1, 3}},
			want:  []int{1},
		},
		{
			name:  "path has every interior vertex",
			n:     4,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 3}},
			want:  []int{1, 2},
		},
		{
			name:  "cycle has none",
			n:     4,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 3}, {3, 0}},
			want:  []int{},
		},
		{
			name:  "star has only its hub",
			n:     5,
			edges: [][2]int{{0, 1}, {0, 2}, {0, 3}, {0, 4}},
			want:  []int{0},
		},
		{
			name:  "single edge has neither end",
			n:     2,
			edges: [][2]int{{0, 1}},
			want:  []int{},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := ArticulationPoints(c.n, buildAdj(c.n, c.edges))
			if !sameVertices(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestArticulationPointsTwoCyclesSharingOneVertex(t *testing.T) {
	// Two triangles joined at vertex 2. Nothing inside a cycle is a cut
	// vertex, but the vertex the two cycles share is.
	n := 5
	edges := [][2]int{{0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 2}}
	want := []int{2}

	got := ArticulationPoints(n, buildAdj(n, edges))
	if !sameVertices(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestArticulationPointsDisconnectedGraph(t *testing.T) {
	n := 8
	// Two separate pieces plus two vertices with no edges at all.
	edges := [][2]int{{0, 1}, {1, 2}, {3, 4}, {4, 5}, {5, 3}}

	got := ArticulationPoints(n, buildAdj(n, edges))
	want := []int{1}
	if !sameVertices(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestArticulationPointsResultIsSortedAscending(t *testing.T) {
	// Three arms off vertex 0, each one vertex longer than a leaf. The order
	// the vertices are discovered in is not ascending, so a result collected
	// as the traversal unwinds has to be put in order before it is returned.
	n := 7
	edges := [][2]int{{0, 4}, {4, 5}, {0, 3}, {3, 6}, {0, 1}, {1, 2}}

	got := ArticulationPoints(n, buildAdj(n, edges))
	want := []int{0, 1, 3, 4}
	if !sameVertices(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestArticulationPointsHandlesLargeGraphInOneTraversal(t *testing.T) {
	// A perfect binary tree: every internal vertex is a cut vertex, every leaf
	// is not. Removing one vertex at a time and recounting components would
	// need billions of steps here; a single traversal needs a few tens of
	// thousands.
	const n = 131071
	edges := make([][2]int, 0, n)
	for parent := 0; 2*parent+1 < n; parent++ {
		edges = append(edges, [2]int{parent, 2*parent + 1})
		edges = append(edges, [2]int{parent, 2*parent + 2})
	}
	adj := buildAdj(n, edges)

	want := make([]int, 0, n/2)
	for u := 0; 2*u+1 < n; u++ {
		want = append(want, u)
	}

	const budget = 2 * time.Second
	start := time.Now()
	got := ArticulationPoints(n, adj)
	elapsed := time.Since(start)

	if !sameVertices(got, want) {
		if len(got) != len(want) {
			t.Fatalf("got %d cut vertices, want %d", len(got), len(want))
		}
		t.Fatalf("wrong cut vertices for the large graph")
	}
	if elapsed > budget {
		t.Fatalf("took %v on a graph of %d vertices, over the %v budget: the whole graph has to be settled in one traversal, not one search per removed vertex", elapsed, n, budget)
	}
}

