package exercise

import "sort"

func ArticulationPoints(n int, adj [][]int) []int {
	disc := make([]int, n)
	low := make([]int, n)
	isAP := make([]bool, n)
	timer := 0

	var dfs func(u, parent int)
	dfs = func(u, parent int) {
		timer++
		disc[u], low[u] = timer, timer
		children := 0

		for _, v := range adj[u] {
			if v == parent {
				continue
			}
			if disc[v] != 0 {
				low[u] = min(low[u], disc[v])
				continue
			}
			children++
			dfs(v, u)
			low[u] = min(low[u], low[v])
			if parent != -1 && low[v] >= disc[u] {
				isAP[u] = true
			}
		}
		if parent == -1 && children > 1 {
			isAP[u] = true
		}
	}

	for u := 0; u < n; u++ {
		if disc[u] == 0 {
			dfs(u, -1)
		}
	}

	res := []int{}
	for u := 0; u < n; u++ {
		if isAP[u] {
			res = append(res, u)
		}
	}
	sort.Ints(res)
	return res
}
